import{_ as a,c as n,o as s,ag as t}from"./chunks/framework.Bzez9NG9.js";const m=JSON.parse('{"title":"Planning Analytics","description":"Use SPACE to understand, search, manage, troubleshoot, and version IBM Planning Analytics and TM1 models across connected environments.","frontmatter":{"title":"Planning Analytics","description":"Use SPACE to understand, search, manage, troubleshoot, and version IBM Planning Analytics and TM1 models across connected environments.","keywords":["IBM Planning Analytics","Planning Analytics","TM1","model documentation","model search","releases","deployments","user access","TM1 logs","Git"],"outline":"deep"},"headers":[],"relativePath":"doc/planning-analytics/index.md","filePath":"doc/planning-analytics/index.md"}'),o={name:"doc/planning-analytics/index.md"};function i(r,e,l,d,c,p){return s(),n("div",null,e[0]||(e[0]=[t('<h1 id="planning-analytics" tabindex="-1">Planning Analytics <a class="header-anchor" href="#planning-analytics" aria-label="Permalink to &quot;Planning Analytics&quot;">​</a></h1><p>SPACE provides a set of capabilities for working with IBM Planning Analytics and TM1 models beyond the standard development and administration experience. Use them to understand model structure, find objects and dependencies, manage changes across environments, investigate user access, analyze TM1 logs, and bring model development under version control.</p><p>These capabilities work with configured Planning Analytics connections and complement the <a href="./../ai/">AI Assistant</a> and <a href="./../python/">Python</a> features in SPACE.</p><h2 id="model-documentation" tabindex="-1">Model documentation <a class="header-anchor" href="#model-documentation" aria-label="Permalink to &quot;Model documentation&quot;">​</a></h2><p>Generate and explore documentation for Planning Analytics models, making complex TM1 applications easier to understand and maintain.</p><p>Use model documentation to capture model structure and relationships in a form that can be reviewed by developers, administrators, and other users.</p><p><a href="./model-documentation.html">Learn about model documentation</a></p><h2 id="model-search" tabindex="-1">Model search <a class="header-anchor" href="#model-search" aria-label="Permalink to &quot;Model search&quot;">​</a></h2><p>Search across TM1 model objects to quickly find where business concepts, object names, or logic are used.</p><p>Model search helps developers navigate large Planning Analytics applications without manually opening individual cubes, rules, dimensions, or processes.</p><p><a href="./model-search.html">Learn about model search</a></p><h2 id="releases-and-deployments" tabindex="-1">Releases and deployments <a class="header-anchor" href="#releases-and-deployments" aria-label="Permalink to &quot;Releases and deployments&quot;">​</a></h2><p>Manage Planning Analytics changes across environments, including comparing environments and working with model releases.</p><p>Use these capabilities when reviewing differences between development, test, and production environments or preparing model changes for deployment.</p><p><a href="./releases-and-deployments.html">Learn about releases and deployments</a></p><h2 id="users-and-access" tabindex="-1">Users and access <a class="header-anchor" href="#users-and-access" aria-label="Permalink to &quot;Users and access&quot;">​</a></h2><p>Analyze and troubleshoot user access to Planning Analytics models.</p><p>Use <strong>Users and access</strong> to understand user permissions and investigate access to TM1 objects when diagnosing security or access issues.</p><p><a href="./users-and-access.html">Learn about users and access</a></p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p>Search and analyze IBM Planning Analytics audit, transaction, and server logs in SPACE.</p><p>Use the different log types to investigate server activity, trace data changes, review audit events, and support troubleshooting without leaving SPACE.</p><p><a href="./logs.html">Learn about logs</a></p><h2 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h2><p>Use Git with Planning Analytics model development to track changes and maintain model objects in version control.</p><p>The Planning Analytics Git integration is separate from Git support in the SPACE Python environment.</p><p><a href="./git.html">Learn about Planning Analytics Git</a></p>',27)]))}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
